import { Avatar } from '@refy-design/web';
import { Item } from '@refy-design/web';
import { useState } from 'react';
function ItemExample() {
  const [selected, setSelected] = useState(false);
  return (
    <Item
      title="Content guide"
      description={selected ? 'Material selected' : '12 pages · updated today'}
      media={<Avatar initials="GC" shape="square" />}
      selected={selected}
      onClick={() => setSelected(!selected)}
    />
  );
}
export function Example() {
  return <ItemExample />;
}

